public class PricePrinterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected [" + expected + "] but got [" + actual + "]");
            failures++;
        }
    }

    static String capture(String name, double price) {
        java.io.ByteArrayOutputStream buf = new java.io.ByteArrayOutputStream();
        java.io.PrintStream old = System.out;
        System.setOut(new java.io.PrintStream(buf));
        try {
            PricePrinter.printPrice(name, price);
        } finally {
            System.setOut(old);
        }
        return buf.toString().replace(System.lineSeparator(), "\n");
    }

    public static void main(String[] args) {
        java.util.Locale.setDefault(java.util.Locale.US);
        check("printPrice(\"apple\", 1.5)", "apple      $  1.50\n", capture("apple", 1.5));
        check("printPrice(\"bread\", 12.0)", "bread      $ 12.00\n", capture("bread", 12.0));
        check("printPrice(\"chocolates\", 3.25) 10-char name", "chocolates $  3.25\n", capture("chocolates", 3.25));
        check("printPrice(\"tea\", 999.99) fills width", "tea        $999.99\n", capture("tea", 999.99));
        check("printPrice(\"x\", 0.0)", "x          $  0.00\n", capture("x", 0.0));
        check("printPrice(\"blueberries\", 2.75) long name", "blueberries $  2.75\n", capture("blueberries", 2.75));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

